import { mkdir, readFile, writeFile } from "node:fs/promises";
import { join, resolve } from "node:path";
import { scanAssets } from "./scanner";
import type { GenerateResult, ResolvedConfig, ScannedAsset } from "./types";
import { pkg } from "../pkg.config";

const HEADER = `/*
 * ╔══════════════════════════════════════════════╗
 * ║  This file is automatically generated by     ║
 * ║  ${pkg.name} - typed asset paths for TypeScript.  ║
 * ║                                              ║
 * ║  Any edits you make here will be silently    ║
 * ║  overwritten the next time you run the dev   ║
 * ║  server or build your project.               ║
 * ║                                              ║
 * ║  To change which assets are included, edit   ║
 * ║  your vite config (typedAssets sources).     ║
 * ╚══════════════════════════════════════════════╝
 */
`;

/**
 * Pure function: turns scanned assets into the contents of the generated files.
 * Keys are file names inside the output folder.
 */
export function renderManifest(assets: ScannedAsset[]): Record<string, string> {
  const paths = assets.map((asset) => JSON.stringify(asset.path));
  const union = paths.length > 0 ? paths.join(" | ") : "never";
  const tuple = paths.length > 0 ? `[${paths.join(", ")}]` : "[]";

  return {
    // Teaches TypeScript which paths exist. Picked up through tsconfig "include".
    "register.d.ts": `${HEADER}
declare module "${pkg.name}" {
  interface Register {
    paths: ${union};
  }
}

export {};
`,

    // Runtime list of paths.
    "manifest.js": `${HEADER}
export const paths = ${tuple};
`,

    // Types for the runtime module.
    "manifest.d.ts": `${HEADER}
export declare const paths: readonly ${tuple};
export type AssetPath = (typeof paths)[number];
`,
  };
}

/** Only touch the disk when content changed, so watchers and HMR don't loop. */
async function writeIfChanged(file: string, content: string): Promise<boolean> {
  try {
    if ((await readFile(file, "utf8")) === content) return false;
  } catch {
    // file doesn't exist yet
  }
  await writeFile(file, content);
  return true;
}

/** Scan the asset folders and write the manifest files. */
export async function generate(
  config: ResolvedConfig,
): Promise<GenerateResult> {
  const assets = await scanAssets(config);
  const outDir = resolve(config.root, config.outDir);
  await mkdir(outDir, { recursive: true });

  const files = renderManifest(assets);
  const results = await Promise.all(
    Object.entries(files).map(([name, content]) =>
      writeIfChanged(join(outDir, name), content),
    ),
  );

  return { assets, outDir, changed: results.some(Boolean) };
}
